'use strict';
const $=id=>document.getElementById(id),keys=new Set(),player=new THREE.Vector3(3,1.65,13),clock=new THREE.Clock();
let yaw=0,pitch=0,started=false,paused=false,phase='approach',phaseTime=0,dialogUntil=0,routeIndex=0,doorProgress=0,mazeOpen=false,footTimer=0,audio;
const route=[new THREE.Vector3(0,1,9),new THREE.Vector3(0,1,4.8),new THREE.Vector3(2.9,1,1),new THREE.Vector3(3,1,-5.3),new THREE.Vector3(3,1,-7.25)];
verity.position.set(3.5,1,20);verity.rotation.y=Math.PI;camera.rotation.order='YXZ';
scene.background=new THREE.Color(0x8b9880);scene.fog=new THREE.Fog(0x8b9880,25,95);hemi.intensity=2.2;sun.intensity=2.3;
// A grass field occupies the enclosed forecourt; paths remain at the perimeter.
box(18,.07,18,0,.08,19,0x66704b);
let seed=92;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
const blades=new THREE.InstancedMesh(new THREE.PlaneGeometry(.045,.25),new THREE.MeshStandardMaterial({color:0x687847,side:THREE.DoubleSide,roughness:1}),7500),dummy=new THREE.Object3D();
for(let i=0;i<7500;i++){dummy.position.set(-9+rand()*18,.24,10+rand()*18);dummy.rotation.y=rand()*Math.PI;dummy.scale.setScalar(.5+rand());dummy.updateMatrix();blades.setMatrixAt(i,dummy.matrix);}scene.add(blades);
// Keep the field clear for the encounter; playground equipment remains to its sides.
const lawnObstacles=[];scene.traverse(o=>{if(o.isMesh&&o!==blades&&o.position.z>10&&o.position.z<28&&Math.abs(o.position.x)<9&&o.position.y>.12&&o.position.y<3.6&&o.parent===scene)lawnObstacles.push(o);});lawnObstacles.forEach(o=>{o.position.x-=10;});
// Full-height partitions at eye level; an actual hinged door seals the quiet room.
const hinge=new THREE.Group();hinge.position.set(1.98,0,-6.48);scene.add(hinge);const door=box(2,2.9,.13,1,1.45,0,0x52736c,hinge);sphere(.065,1.76,1.3,.13,0xbda76a,hinge);hinge.rotation.y=-Math.PI/2;
const colliders=[];scene.updateMatrixWorld(true);scene.traverse(o=>{if(!o.isMesh||o.parent===verity||o===blades||o.parent===hinge)return;const b=new THREE.Box3().setFromObject(o);const sz=b.getSize(new THREE.Vector3());if(b.min.y<1.6&&b.max.y>.45&&sz.y>.35&&(sz.x>.3||sz.z>.3))colliders.push(b);});
const doorBox=new THREE.Box3(new THREE.Vector3(1.95,0,-6.62),new THREE.Vector3(4.05,3,-6.35));
function blocked(x,z){const radius=.23;const list=phase==='locked'?[...colliders,doorBox]:colliders;return list.some(b=>x>b.min.x-radius&&x<b.max.x+radius&&z>b.min.z-radius&&z<b.max.z+radius);}
function sound(freq,duration=.1,volume=.04,type='sine'){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function say(text,seconds=5){$('subtitle').hidden=false;$('subtitle').querySelector('p').textContent=text;dialogUntil=performance.now()+seconds*1000;}
function objective(text){$('objective').textContent=text;}
function begin(){if(!started){started=true;try{audio=new(window.AudioContext||window.webkitAudioContext)();}catch{}$('menu').hidden=true;$('objective').hidden=false;$('controls').hidden=false;$('crosshair').hidden=false;objective('LOOK AROUND');}paused=false;$('pause').hidden=true;keys.clear();if(matchMedia('(pointer:coarse)').matches)$('touch').hidden=false;else{const request=renderer.domElement.requestPointerLock?.();request?.catch?.(()=>{});}clock.getDelta();}
function pause(){if(!started||mazeOpen)return;paused=true;keys.clear();$('pause').hidden=false;$('touch').hidden=true;document.exitPointerLock?.();}
$('begin').addEventListener('click',begin);$('resume').addEventListener('click',begin);$('restart').addEventListener('click',()=>location.reload());
document.addEventListener('pointerlockchange',()=>{if(started&&!document.pointerLockElement&&!mazeOpen&&!paused&&!matchMedia('(pointer:coarse)').matches)pause();});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!paused&&!mazeOpen){yaw-=e.movementX*.002;pitch=Math.max(-1.2,Math.min(1.2,pitch-e.movementY*.002));}});
let touchLook=null;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touchLook=[e.clientX,e.clientY];else if(started&&!paused&&!mazeOpen&&!document.pointerLockElement)renderer.domElement.requestPointerLock?.();});renderer.domElement.addEventListener('pointermove',e=>{if(!touchLook||paused||mazeOpen)return;yaw-=(e.clientX-touchLook[0])*.005;pitch=Math.max(-1.2,Math.min(1.2,pitch-(e.clientY-touchLook[1])*.005));touchLook=[e.clientX,e.clientY];});window.addEventListener('pointerup',()=>touchLook=null);
function nearDoor(){return player.distanceTo(new THREE.Vector3(3,1.65,-7.2))<1.8;}function nearMaze(){return player.distanceTo(new THREE.Vector3(3,1.65,-8.2))<2.2;}
function interact(){if(mazeOpen){closeMaze();return;}if(phase==='locked'&&nearMaze()){openMaze();return;}if(phase==='locked'&&nearDoor()){sound(85,.15,.07,'square');$('prompt').textContent='LOCKED';setTimeout(()=>{$('prompt').hidden=true;},1300);}}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(mazeOpen)closeMaze();else if(started&&!paused)pause();return;}if(e.code==='KeyE'&&!e.repeat){interact();return;}if(mazeOpen){const map={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(map[e.code]&&!e.repeat)moveMaze(...map[e.code]);return;}keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(started&&!mazeOpen)pause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(b.dataset.key);b.setPointerCapture(e.pointerId);});['pointerup','pointercancel','lostpointercapture'].forEach(t=>b.addEventListener(t,()=>keys.delete(b.dataset.key)));});$('touch-use').addEventListener('click',interact);
function openMaze(){mazeOpen=true;keys.clear();$('maze').hidden=false;$('prompt').hidden=true;document.exitPointerLock?.();drawMaze();$('close-maze').focus();}function closeMaze(){mazeOpen=false;$('maze').hidden=true;begin();}$('close-maze').addEventListener('click',closeMaze);
const mazeContext=$('maze-canvas').getContext('2d');let mazeMoves=0,mazeWon=false;
function drawMaze(){const c=mazeContext;c.fillStyle='#c8b58c';c.fillRect(0,0,490,490);for(let r=0;r<7;r++)for(let col=0;col<7;col++){c.fillStyle=mazeRows[r][col]==='#'?'#43685e':'#c8b58c';c.fillRect(col*70+2,r*70+2,66,66);}c.fillStyle='#58874d';c.fillRect(5*70+13,5*70+13,44,44);c.fillStyle='#efd252';c.beginPath();c.arc(marbleCell[0]*70+35,marbleCell[1]*70+35,19,0,Math.PI*2);c.fill();}
function moveMaze(dx,dy){if(mazeWon)return;const nx=marbleCell[0]+dx,ny=marbleCell[1]+dy;if(mazeRows[ny]?.[nx]!=='.'){sound(120,.04,.015);return;}marbleCell=[nx,ny];mazeMoves++;marble.position.set(mazeOrigin.x+nx*cell,1.07,mazeOrigin.z+ny*cell);mazeWon=nx===5&&ny===5;$('maze-text').textContent=mazeWon?'Finished. He still hasn’t come back.':mazeMoves+' moves';sound(mazeWon?660:360,.07,.02);drawMaze();}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>moveMaze(...b.dataset.step.split(',').map(Number))));$('reset-maze').addEventListener('click',()=>{marbleCell=[1,1];mazeMoves=0;mazeWon=false;marble.position.set(mazeOrigin.x+cell,1.07,mazeOrigin.z+cell);$('maze-text').textContent='Find the green corner.';drawMaze();});
function walkNPC(target,dt,speed){const delta=target.clone().sub(verity.position);delta.y=0;const len=delta.length();if(len<.08)return true;delta.normalize();verity.position.addScaledVector(delta,Math.min(len,speed*dt));verity.rotation.y=Math.atan2(delta.x,delta.z);return false;}
function updateStory(dt){phaseTime+=dt;const distance=player.distanceTo(verity.position);if(phase==='approach'){if(walkNPC(new THREE.Vector3(3,1,15.6),dt,1.4)){phase='greeting';phaseTime=0;verity.rotation.y=Math.PI;say('hey! you look quite a bit lost. how about you come with me!',6);objective('LISTEN TO VERITY');}}
 else if(phase==='greeting'&&phaseTime>6){phase='follow';phaseTime=0;objective('FOLLOW VERITY');}
 else if(phase==='follow'){if(distance<6&&routeIndex<route.length){if(walkNPC(route[routeIndex],dt,1.6))routeIndex++;}if(routeIndex>=route.length&&player.z<-6.9&&Math.abs(player.x-3)<1.2){phase='departure';phaseTime=0;say("oh! I've got something to do... I'll be right back!",5.5);objective('WAIT FOR VERITY');}}
 else if(phase==='departure'&&phaseTime>5.5){if(walkNPC(new THREE.Vector3(3,1,-4.5),dt,1.9)){phase='closing';phaseTime=0;}}
 else if(phase==='closing'){doorProgress=Math.min(1,phaseTime/.8);hinge.rotation.y=-Math.PI/2*(1-doorProgress);if(doorProgress===1){phase='locked';phaseTime=0;verity.visible=false;sound(62,.35,.18,'sawtooth');setTimeout(()=>sound(170,.08,.09,'square'),230);objective('WAIT HERE');}}
 if(performance.now()>dialogUntil)$('subtitle').hidden=true;
}
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(started&&!paused&&!mazeOpen){let f=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),s=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0);const len=Math.hypot(f,s);if(len){f/=len;s/=len;const speed=keys.has('ShiftLeft')?4:2.5;const dx=(-Math.sin(yaw)*f+Math.cos(yaw)*s)*speed*dt,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*s)*speed*dt;if(!blocked(player.x+dx,player.z))player.x+=dx;if(!blocked(player.x,player.z+dz))player.z+=dz;player.x=Math.max(-14.4,Math.min(14.4,player.x));player.z=Math.max(-11,Math.min(30.7,player.z));footTimer+=dt;if(footTimer>.48){footTimer=0;sound(player.z>7?75:105,.055,.018,'triangle');}}updateStory(dt);$('prompt').hidden=true;if(phase==='locked'&&nearMaze()){$('prompt').hidden=false;$('prompt').textContent='[E] PLAY MARBLE MAZE';}else if(phase==='locked'&&nearDoor()){$('prompt').hidden=false;$('prompt').textContent='[E] TRY DOOR';}}
camera.position.copy(player);camera.rotation.set(pitch,yaw,0);renderer.render(scene,camera);}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();
// Initially face Verity across the grass.
yaw=Math.PI;frame();
